import { Schema } from 'effect'

import {
  PermissivePassthrough,
  mutableEncoded,
  OrNullAsOptional,
  StructNoContext,
} from '@wildflowerhealthio/kitchen-sink/schema'

import type * as FhirR4 from 'fhir/r4.d.ts'

import * as BackboneElement from '../base/backbone-element.ts'
import * as Resource from '../base/resource.ts'
import { IdentifierSchema } from '../complex/identifier-and-reference.ts'

const BundleType = Schema.Enums({
  batch: 'batch',
  'batch-response': 'batch-response',
  collection: 'collection',
  document: 'document',
  history: 'history',
  message: 'message',
  searchset: 'searchset',
  transaction: 'transaction',
  'transaction-response': 'transaction-response',
} as const)

const EntryRequestMethod = Schema.Enums({
  DELETE: 'DELETE',
  GET: 'GET',
  HEAD: 'HEAD',
  PATCH: 'PATCH',
  POST: 'POST',
  PUT: 'PUT',
} as const)

// FHIR R4 § Bundle.entry.request — required on transaction/batch entries.
const EntryRequestStruct = mutableEncoded(
  StructNoContext({
    ...BackboneElement.fields,
    method: EntryRequestMethod,
    url: Schema.String,
    ifNoneMatch: OrNullAsOptional(Schema.String),
    ifModifiedSince: OrNullAsOptional(Schema.String),
    ifMatch: OrNullAsOptional(Schema.String),
    ifNoneExist: OrNullAsOptional(Schema.String),
  })
)

const EntryRequestSchema: Schema.Schema<
  typeof EntryRequestStruct.Type,
  FhirR4.BundleEntryRequest,
  never
> = EntryRequestStruct

// FHIR R4 § OperationOutcome.issue.details — only `text` is read here (a
// human-readable message); the coded part is not modeled.
const OperationOutcomeDetailsStruct = mutableEncoded(
  StructNoContext({
    ...BackboneElement.fields,
    text: OrNullAsOptional(Schema.String),
  })
)

// FHIR R4 § OperationOutcome.issue. `severity`/`code` are the spec's coded
// value sets, but a batch-response only needs them rendered, so they stay
// `Schema.String` (the server's exact token) rather than mirroring the full
// enums.
const OperationOutcomeIssueStruct = mutableEncoded(
  StructNoContext({
    ...BackboneElement.fields,
    severity: Schema.String,
    code: Schema.String,
    diagnostics: OrNullAsOptional(Schema.String),
    details: OrNullAsOptional(OperationOutcomeDetailsStruct),
  })
)

// FHIR R4 § OperationOutcome — modeled only as far as a caller needs to
// render its diagnostics: a batch-response entry's (`Bundle.entry.response.outcome`,
// which the spec types as any `Resource`), or the body a server answers a
// refused Bundle with. Not a member of `FhirResourceSchema`: it is never
// stored on its own. `resourceType`
// stays `Schema.String` (not a literal) so this stays mutually assignable with
// the base `Resource` the entry-response schema is pinned against — the
// server always sends `"OperationOutcome"` here regardless.
const OperationOutcomeStruct = mutableEncoded(
  StructNoContext({
    resourceType: Schema.String,
    issue: Schema.optionalWith(mutableEncoded(Schema.Array(OperationOutcomeIssueStruct)), {
      default: (): readonly (typeof OperationOutcomeIssueStruct.Type)[] => [],
    }),
  })
)

/**
 * The OpenAPI projection of {@link OperationOutcomeStruct}, written out as the
 * Bundle's is: the struct's backbone fields carry no JSON Schema of their own.
 */
const operationOutcomeJsonSchema = {
  type: 'object',
  title: 'OperationOutcome',
  description:
    'A collection of error, warning, or information messages that result from a system action.',
  required: ['resourceType'],
  properties: {
    resourceType: { type: 'string', enum: ['OperationOutcome'] },
    issue: {
      type: 'array',
      description: 'An error, warning, or information message that results from a system action.',
      items: {
        type: 'object',
        required: ['severity', 'code'],
        properties: {
          severity: { type: 'string', description: 'fatal | error | warning | information' },
          code: { type: 'string', description: 'Error or warning code.' },
          diagnostics: {
            type: 'string',
            description: 'Additional diagnostic information about the issue.',
          },
          details: {
            type: 'object',
            properties: { text: { type: 'string' } },
            description: 'Additional details about the error.',
          },
        },
      },
    },
  },
} as const

/** An OperationOutcome on its own: the body a server answers a refused Bundle with. */
const OperationOutcomeSchema = OperationOutcomeStruct.annotations({
  identifier: 'OperationOutcome',
  jsonSchema: operationOutcomeJsonSchema,
})

// FHIR R4 § Bundle.entry.response — populated on transaction/batch-response.
// `outcome` carries an OperationOutcome with the entry's diagnostics (errors
// on a batch failure, hints/warnings otherwise).
const EntryResponseStruct = mutableEncoded(
  StructNoContext({
    ...BackboneElement.fields,
    status: Schema.String,
    location: OrNullAsOptional(Schema.String),
    etag: OrNullAsOptional(Schema.String),
    lastModified: OrNullAsOptional(Schema.DateTimeUtc),
    outcome: OrNullAsOptional(OperationOutcomeStruct),
  })
)

const EntryResponseSchema: Schema.Schema<
  typeof EntryResponseStruct.Type,
  FhirR4.BundleEntryResponse,
  never
> = EntryResponseStruct

const EntrySearchMode = Schema.Enums({
  include: 'include',
  match: 'match',
  outcome: 'outcome',
} as const)

// FHIR R4 § Bundle.entry.search — present on searchset bundles.
const EntrySearchStruct = mutableEncoded(
  StructNoContext({
    ...BackboneElement.fields,
    mode: OrNullAsOptional(EntrySearchMode),
    score: OrNullAsOptional(Schema.Number.pipe(Schema.finite())),
  })
)

const EntrySearchSchema: Schema.Schema<
  typeof EntrySearchStruct.Type,
  FhirR4.BundleEntrySearch,
  never
> = EntrySearchStruct

// FHIR R4 § BundleLink — same shape for top-level Bundle.link and entry.link.
const BundleLinkStruct = mutableEncoded(
  StructNoContext({
    ...BackboneElement.fields,
    relation: Schema.String,
    url: Schema.String,
  })
)

const BundleLinkSchema: Schema.Schema<typeof BundleLinkStruct.Type, FhirR4.BundleLink, never> =
  BundleLinkStruct

/**
 * Decoded shape of a Bundle entry, parameterised by the decoded resource
 * type. Written out explicitly (rather than inferred from the struct) so the
 * generic {@link EntrySchema} factory can carry a portable return type.
 */
interface EntryType<Content> extends Schema.Struct.Type<typeof BackboneElement.fields> {
  readonly fullUrl: URL | null
  readonly link: readonly (typeof BundleLinkSchema.Type)[]
  readonly request: typeof EntryRequestSchema.Type | null
  readonly resource: Content | null
  readonly response: typeof EntryResponseSchema.Type | null
  readonly search: typeof EntrySearchSchema.Type | null
}

const EntrySchema = <ContentTypeSchema extends Schema.Schema.AnyNoContext>(
  contentTypeSchema: ContentTypeSchema
): Schema.Schema<
  EntryType<Schema.Schema.Type<ContentTypeSchema>>,
  Omit<FhirR4.BundleEntry, 'resource'> & {
    resource?: Schema.Schema.Encoded<ContentTypeSchema> | undefined
  },
  never
> =>
  mutableEncoded(
    StructNoContext({
      ...BackboneElement.fields,
      fullUrl: OrNullAsOptional(Schema.URL),
      link: Schema.optionalWith(mutableEncoded(Schema.Array(BundleLinkSchema)), {
        default: (): readonly (typeof BundleLinkSchema.Type)[] => [],
      }),
      request: OrNullAsOptional(EntryRequestSchema),
      resource: OrNullAsOptional(contentTypeSchema),
      response: OrNullAsOptional(EntryResponseSchema),
      search: OrNullAsOptional(EntrySearchSchema),
    })
  )

const bundleTypeEnum = [
  'document',
  'message',
  'transaction',
  'transaction-response',
  'batch',
  'batch-response',
  'history',
  'searchset',
  'collection',
] as const

const bundleJsonSchema = {
  type: 'object',
  title: 'Bundle',
  description: 'A container for a collection of resources.',
  required: ['resourceType', 'type'],
  properties: {
    resourceType: { type: 'string', enum: ['Bundle'] },
    id: { type: 'string', description: 'Logical id of this artifact.' },
    meta: { type: 'object', description: 'Metadata about the resource.' },
    implicitRules: { type: 'string', format: 'uri' },
    language: { type: 'string', description: 'Language of the resource content.' },
    identifier: {
      type: 'object',
      description:
        'A persistent identifier for the bundle that will not change as a bundle is copied from server to server.',
    },
    type: {
      type: 'string',
      enum: bundleTypeEnum,
      description: 'Indicates the purpose of this bundle - how it is intended to be used.',
    },
    timestamp: {
      type: 'string',
      format: 'date-time',
      description: 'The date/time that the bundle was assembled.',
    },
    total: {
      type: 'integer',
      description:
        'If a set of search matches, this is the (potentially estimated) total number of entries of type "match" across all pages in the search.',
    },
    link: {
      type: 'array',
      items: { type: 'object' },
      description: 'A series of links that provide context to this bundle.',
    },
    entry: {
      type: 'array',
      items: {
        type: 'object',
        description:
          'An entry in a bundle resource - will either contain a resource or information about a resource (transactions and history only).',
        properties: {
          fullUrl: { type: 'string' },
          link: { type: 'array', items: { type: 'object' } },
          request: { type: 'object' },
          resource: { type: 'object' },
          response: { type: 'object' },
          search: { type: 'object' },
        },
      },
      description: 'An entry in a bundle resource.',
    },
    signature: {
      type: 'object',
      description: 'Digital Signature - base64 encoded. XML-DSig or a JWT.',
    },
  },
} as const

/**
 * Decoded shape of a Bundle, parameterised by the decoded entry resource
 * type. Written out explicitly so the generic {@link BundleSchema} factory
 * can carry a portable return type.
 */
interface BundleValue<Content> extends Schema.Struct.Type<typeof Resource.fields> {
  readonly resourceType: 'Bundle'
  readonly entry: readonly EntryType<Content>[]
  readonly identifier: typeof IdentifierSchema.Type | null
  readonly link: readonly (typeof BundleLinkSchema.Type)[]
  readonly signature: unknown
  readonly timestamp: string | null
  readonly total: number | null
  readonly type: typeof BundleType.Type
}

const BundleSchema = <FhirResourceSchema extends Schema.Schema.AnyNoContext>(
  resourceSchema: FhirResourceSchema
): Schema.Schema<
  BundleValue<Schema.Schema.Type<FhirResourceSchema>>,
  FhirR4.Bundle<Schema.Schema.Encoded<FhirResourceSchema>>,
  never
> =>
  Schema.extend(
    StructNoContext({ resourceType: Schema.Literal('Bundle') }),
    mutableEncoded(
      StructNoContext({
        ...Resource.fields,
        entry: Schema.optionalWith(mutableEncoded(Schema.Array(EntrySchema(resourceSchema))), {
          default: (): [] => [],
        }),
        identifier: OrNullAsOptional(Schema.suspend(() => IdentifierSchema)),
        link: Schema.optionalWith(mutableEncoded(Schema.Array(BundleLinkSchema)), {
          default: (): readonly (typeof BundleLinkSchema.Type)[] => [],
        }),
        signature: OrNullAsOptional(PermissivePassthrough),
        timestamp: OrNullAsOptional(Schema.String),
        total: OrNullAsOptional(Schema.Int),
        type: BundleType,
      })
    )
  ).annotations({ jsonSchema: bundleJsonSchema })

/** Decoded shape of a Bundle entry's `response` — including the `outcome` OperationOutcome. */
type EntryResponseType = typeof EntryResponseSchema.Type

/** Decoded shape of an OperationOutcome, as far as its issues' rendering goes. */
type OperationOutcomeType = typeof OperationOutcomeStruct.Type

export {
  BundleType,
  type EntryResponseType,
  EntrySchema,
  OperationOutcomeSchema,
  type OperationOutcomeType,
  BundleSchema as Schema,
  type BundleValue,
}
