import { withMandatoryId } from '@wildflowerhealthio/fhir-r4/data-types'
import { MedicationRequest } from '@wildflowerhealthio/fhir-r4/resources'
import type { Effect, Schema } from 'effect'
import type Client from 'fhirclient/Client'

import {
  RESOURCE_PAGE_SIZE,
  type BundleDecodeError,
  type ResourcePageRequestError,
  fetchResourcePage,
  type PagedResourceRead,
  type ResourcePage,
} from './resource-page.ts'

/**
 * The schema every `MedicationRequest` entry decodes through: the R4 resource
 * with its `id` required, as the FHIR server always returns one. An entry
 * without an `id` fails the decode.
 */
const MedicationRequestWithIdSchema = withMandatoryId(MedicationRequest.Schema)

/** The decoded FHIR R4 `MedicationRequest` resource, `id` present. */
type MedicationRequestResource = Schema.Schema.Type<typeof MedicationRequestWithIdSchema>

/**
 * One page of a `MedicationRequest` read: the decoded resources on this page and
 * the cursor to the next page (`null` when this is the last page).
 */
type MedicationRequestPage = ResourcePage<MedicationRequestResource>

/**
 * The cursor {@link fetchMedicationRequestPage} reads from. The first page is
 * opened by patient scope — a `string` patientId, or `null` for a `system/`
 * launch with no patient in context — and every subsequent page by the absolute
 * `next`-link URL the previous page returned.
 */
type MedicationRequestCursor = { readonly patientId: string | null } | { readonly pageUrl: string }

// Newest-authored first, server-side, so scroll paging can append each page
// without reordering rows already on screen. `authoredon` is the FHIR R4
// `MedicationRequest` search parameter backing the `authoredOn` element.
const ALWAYS_PRESENT_PARAMS = `_count=${RESOURCE_PAGE_SIZE}&_sort=-authoredon`

/**
 * The `MedicationRequest` read: patient-scoped when a patient is in context, a
 * pinned page size.
 */
const medicationRequestRead: PagedResourceRead<
  MedicationRequestResource,
  Schema.Schema.Encoded<typeof MedicationRequestWithIdSchema>,
  string | null
> = {
  resourceType: 'MedicationRequest',
  schema: MedicationRequestWithIdSchema,
  firstPageQuery: (patientId: string | null): string =>
    patientId === null
      ? ALWAYS_PRESENT_PARAMS
      : `patient=${encodeURIComponent(patientId)}&${ALWAYS_PRESENT_PARAMS}`,
}

/**
 * Fetch a single page of `MedicationRequest`s from the SMART FHIR server and
 * report the cursor to the next page, so a caller can page on demand (e.g.
 * scroll-driven loading) instead of reading every page up front.
 *
 * @param client - The SMART client the search is issued through
 * @param cursor - Patient scope for the first page, or a previous page's `nextPageUrl`
 * @returns An effect yielding the page's decoded `MedicationRequest`s and the next page's cursor
 *
 * @remarks
 * A thin patient-scoped wrapper over {@link fetchResourcePage}, which owns the
 * paging, the permissive bundle decode and the per-entry decode-or-drop — an
 * entry without an `id` is dropped and counted like any other that fails to
 * decode. Pages arrive newest-authored first ({@link ALWAYS_PRESENT_PARAMS}),
 * which is what lets a caller append them without reordering earlier rows.
 */
const fetchMedicationRequestPage = (
  client: Client,
  cursor: MedicationRequestCursor
): Effect.Effect<MedicationRequestPage, ResourcePageRequestError | BundleDecodeError> =>
  fetchResourcePage(
    client,
    medicationRequestRead,
    'pageUrl' in cursor ? { pageUrl: cursor.pageUrl } : { first: cursor.patientId }
  )

export {
  fetchMedicationRequestPage,
  type MedicationRequestCursor,
  type MedicationRequestPage,
  type MedicationRequestResource,
}
